from qiskit import QuantumCircuit
import numpy as np

def shor_7mod15() -> QuantumCircuit:
    # Create a quantum circuit with 8 qubits for the phase register and 4 qubits for the modular exponentiation
    qc = QuantumCircuit(12, 8)

    # Initialize the phase register to |1>
    qc.x(0)

    # Apply the modular exponentiation circuits
    def mod_exp(a, power, N):
        return pow(a, power, N)

    # Controlled-U gates for each qubit in the phase register
    for i in range(8):
        for j in range(2**i):
            qc.append(mod_exp(7, 2**(8-i), 15), [8 + k for k in range(4)])

    # Apply the inverse Quantum Fourier Transform (QFT) to the phase register
    def qft_dagger(qc, n):
        """n-qubit QFTdagger the first n qubits in circuit"""
        for qubit in range(n//2):
            qc.swap(qubit, n-qubit-1)
        for j in range(n):
            for m in range(j):
                qc.cp(-np.pi/float(2**(j-m)), m, j)
            qc.h(j)

    qft_dagger(qc, 8)

    # Measure the phase register
    qc.measure(range(8), range(8))

    return qc

